import React, { createContext, useContext, useState, useEffect } from 'react';

const LanguageContext = createContext();

export const useLanguage = () => {
  const context = useContext(LanguageContext);
  if (!context) {
    throw new Error('useLanguage must be used within a LanguageProvider');
  }
  return context;
};

export const LanguageProvider = ({ children }) => {
  const [language, setLanguage] = useState('pt');
  const [nativeLanguage, setNativeLanguage] = useState('pt');
  const [translations, setTranslations] = useState({});
  const [appData, setAppData] = useState(null);
  const [loading, setLoading] = useState(true);

  // Load translations and app data
  useEffect(() => {
    const loadData = () => {
      // Mock translations data
      const mockTranslations = {
        appName: 'LinguaNova',
        navHome: 'Home',
        navDialogues: 'Diálogos',
        navStories: 'Histórias',
        navMyDecks: 'Meus Decks',
        navNewDeck: 'Novo Deck',
        heroTitle: 'Aprenda idiomas de forma natural e divertida',
        heroSubtitle: 'Domine novos idiomas através de diálogos reais, histórias envolventes e flashcards inteligentes.',
        getStarted: 'Começar Agora',
        learnMore: 'Saiba Mais',
        featuresTitle: 'Por que escolher LinguaNova?',
        featuresSubtitle: 'Uma abordagem completa para o aprendizado de idiomas'
      };

      // Mock app data
      const mockAppData = {
        languages: [
          { code: 'pt', flag: 'br', name: 'Português', shortName: 'PT' },
          { code: 'en', flag: 'us', name: 'English', shortName: 'EN' },
          { code: 'es', flag: 'es', name: 'Español', shortName: 'ES' },
          { code: 'fr', flag: 'fr', name: 'Français', shortName: 'FR' },
          { code: 'de', flag: 'de', name: 'Deutsch', shortName: 'DE' },
          { code: 'it', flag: 'it', name: 'Italiano', shortName: 'IT' }
        ]
      };

      setTranslations(mockTranslations);
      setAppData(mockAppData);

      // Load saved language preferences
      const savedLanguage = localStorage.getItem('selectedLanguage') || 'pt';
      const savedNativeLanguage = localStorage.getItem('nativeLanguage') || 'pt';

      setLanguage(savedLanguage);
      setNativeLanguage(savedNativeLanguage);
      setLoading(false);
    };

    loadData();
  }, []);

  const changeLanguage = (newLanguage) => {
    setLanguage(newLanguage);
    localStorage.setItem('selectedLanguage', newLanguage);
  };

  const changeNativeLanguage = (newNativeLanguage) => {
    setNativeLanguage(newNativeLanguage);
    localStorage.setItem('nativeLanguage', newNativeLanguage);
  };

  // Translation function
  const t = (key, fallback = key) => {
    return translations[key] || fallback;
  };

  const value = {
    language,
    nativeLanguage,
    translations,
    appData,
    loading,
    changeLanguage,
    changeNativeLanguage,
    t
  };

  return (
    <LanguageContext.Provider value={value}>
      {children}
    </LanguageContext.Provider>
  );
};
